// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";

/// @title UN1FeeVault
/// @notice The normal-fee vault of the official pool, created by the hook (CREATE child 1, as in Programmable's
///  launch protection v1). The hook mints each swap's normal fee here as UNI claims (ERC-6909 in the PoolManager) and
///  records it in four ledgers, each payable only to its recipient:
///  - platform: 0.30% of every swap, to the fixed platform treasury
///  - developer: the dev fee after the bounty top-up, to the developer
///  - bounty: the reveal bounty reserve, to the beacon
///  - holders: the halving fee, to the distributor
///  The developer is fixed at creation; the distributor and the beacon are bound once by the hook's initializer, before
///  the pool exists. Only accrued fees can leave, to those recipients; anyone may pay the gas of a claim. No owner, no
///  allowances, no principal withdrawal, no arbitrary calls. Opening taxes never enter this vault.
contract UN1FeeVault is IUnlockCallback {
    address public constant PLATFORM_RECIPIENT = 0xD88539d3c4C460136a733A3Fd60cf6BF269079da;

    IPoolManager public immutable poolManager;
    address public immutable kernel; // the hook
    address public immutable uni;
    address public immutable developer;

    address public distributor;
    address public beacon;
    uint256 public platformAccrued;
    uint256 public developerAccrued;
    uint256 public bountyAccrued;
    uint256 public holdersAccrued;

    error NotKernel();
    error NotPoolManager();
    error AlreadyBound();
    error NotBound();
    error InsufficientFeeBacking();
    error NothingToClaim();

    event FeesRecorded(uint256 platform, uint256 developer, uint256 bounty, uint256 holders);
    event FeesClaimed(address indexed recipient, uint256 amount);

    constructor(IPoolManager poolManager_, address uni_, address developer_) {
        poolManager = poolManager_;
        kernel = msg.sender;
        uni = uni_;
        developer = developer_;
    }

    /// @notice Set the holders' and the bounty recipients. The hook's initializer only, once.
    function bind(address distributor_, address beacon_) external {
        if (msg.sender != kernel) revert NotKernel();
        if (distributor != address(0)) revert AlreadyBound();
        if (distributor_ == address(0) || beacon_ == address(0)) revert NotBound();
        distributor = distributor_;
        beacon = beacon_;
    }

    /// @notice Record fees whose UNI claims the hook has just minted to this vault.
    function recordFees(uint256 platform, uint256 developer_, uint256 bounty, uint256 holders) external {
        if (msg.sender != kernel) revert NotKernel();
        platformAccrued += platform;
        developerAccrued += developer_;
        bountyAccrued += bounty;
        holdersAccrued += holders;
        uint256 total = platformAccrued + developerAccrued + bountyAccrued + holdersAccrued;
        if (poolManager.balanceOf(address(this), uint256(uint160(uni))) < total) revert InsufficientFeeBacking();
        emit FeesRecorded(platform, developer_, bounty, holders);
    }

    /// @notice Pay the platform ledger to the platform treasury.
    function claimPlatform() external returns (uint256 amount) {
        amount = platformAccrued;
        platformAccrued = 0;
        _pay(PLATFORM_RECIPIENT, amount);
    }

    /// @notice Pay the developer ledger to the developer.
    function claimDeveloper() external returns (uint256 amount) {
        amount = developerAccrued;
        developerAccrued = 0;
        _pay(developer, amount);
    }

    /// @notice Pay the bounty ledger to the beacon (it calls this when its balance runs short).
    function claimBounty() external returns (uint256 amount) {
        if (beacon == address(0)) revert NotBound();
        amount = bountyAccrued;
        bountyAccrued = 0;
        _pay(beacon, amount);
    }

    /// @notice Pay the holders' ledger to the distributor (its `sync` calls this).
    function claimHolders() external returns (uint256 amount) {
        if (distributor == address(0)) revert NotBound();
        amount = holdersAccrued;
        holdersAccrued = 0;
        _pay(distributor, amount);
    }

    function _pay(address recipient, uint256 amount) private {
        if (amount == 0) revert NothingToClaim();
        poolManager.unlock(abi.encode(recipient, amount));
        emit FeesClaimed(recipient, amount);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        (address recipient, uint256 amount) = abi.decode(data, (address, uint256));
        poolManager.burn(address(this), uint256(uint160(uni)), amount);
        poolManager.take(Currency.wrap(uni), recipient, amount);
        return "";
    }
}

src/UN1Hook.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {Hooks} from "@uniswap/v4-core/src/libraries/Hooks.sol";
import {SafeCast} from "@uniswap/v4-core/src/libraries/SafeCast.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolId, PoolIdLibrary} from "@uniswap/v4-core/src/types/PoolId.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {BalanceDelta, BalanceDeltaLibrary} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {BeforeSwapDelta, BeforeSwapDeltaLibrary, toBeforeSwapDelta} from "@uniswap/v4-core/src/types/BeforeSwapDelta.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {FeeMath} from "./libraries/FeeMath.sol";
import {DrandRound} from "./libraries/DrandRound.sol";
import {UN1FeeVault} from "./UN1FeeVault.sol";
import {UN1ProtectionModule} from "./UN1ProtectionModule.sol";
import {UN1OpeningTaxVault} from "./UN1OpeningTaxVault.sol";

interface IBalanceOf {
    function balanceOf(address account) external view returns (uint256);
}

interface IUN1Token {
    function authorize(uint256 amountIn, uint256 amountOut, uint256 draw) external;
    function authorizeLiquidity(uint256 amountIn, uint256 amountOut) external;
    function composeCount() external view returns (uint256);
    function startProtection() external;
}

/// @title UN1Hook
/// @notice The one permanent hook of the UN1/UNI pool. Immutable, no owner. Its constructor creates, in this order (as
///  Programmable's launch protection v1 does): the normal-fee vault (CREATE child 1), the protection module (child 2) and
///  the opening-tax vault (child 3).
///  - every swap pays a fee in UNI: platform 0.3% + dev 0.3% + halving fee (2.1%, halved every 2,100 composes). The hook
///    mints it as UNI claims to the normal-fee vault, which pays each part only to its fixed recipient
///  - reveal bounties come out of the dev fee: it first tops up a capped reserve for the beacon, the rest goes to the dev;
///    the dev fee of the buys is recorded per drand round, and the beacon pays a round no more than its buys paid
///  - the token may enter or leave the PoolManager only for the exact amounts this hook authorizes (rule ②)
///  - only buys authorize a draw, so only official-pool buys deal new cards (rule ①); liquidity moves naked tokens
///  - launch protection (Programmable launch protection v1, with UNI as the quote): for 5 minutes after the pool is
///    created, buys go through the canonical Universal Router and each buyer (the router's msgSender, authenticated by
///    the protection module) may buy at most 2% of supply in total; the token caps what each address receives the same
///    way. For the first 30 seconds a buy pays a total fee that starts at 99% and falls linearly to the normal fee; the
///    extra is minted to the opening-tax vault, payable only to the platform treasury. The developer and up to six
///    wallets fixed in the module pay no opening tax (the same 2% limits). The launch buy (the pool's first swap, made by
///    the Seeder for the developer) counts as the developer's; marked LAUNCH_BUY, its tokens reach the developer as
///    plain tokens, with no slot (the launch deals no card).
contract UN1Hook is IHooks {
    using PoolIdLibrary for PoolKey;
    using SafeCast for uint256;

    // ---------------- constants ----------------
    uint256 public constant PLATFORM_FEE = 3_000; // 0.30%, fixed by Programmable
    uint256 public constant DEV_FEE = 3_000; // 0.30%
    uint256 public constant HALVING_FEE = 21_000; // 2.10% in epoch 1
    uint256 public constant EPOCH = 2_100; // composes per epoch
    uint256 public constant PROTECTION = 5 minutes; // launch protection window, from pool creation
    uint256 public constant BUYER_LIMIT = 200 ether; // 2% of 10,000, per buyer over the protection window
    uint24 public constant LP_FEE = 0;
    int24 public constant TICK_SPACING = 60;
    address public constant PLATFORM_RECIPIENT = 0xD88539d3c4C460136a733A3Fd60cf6BF269079da;
    uint256 public constant BOUNTY_RESERVE = 50 ether; // UNI kept for reveal bounties, topped up from the dev fee
    /// @notice hookData of the Seeder's launch buy: on the pool's first swap (always the Seeder's, atomic with pool
    ///         creation) it delivers the bought tokens without a draw. Ignored on every later swap.
    bytes32 public constant LAUNCH_BUY = keccak256("un1.launch-buy");

    // ---------------- wiring ----------------
    IPoolManager public immutable poolManager;
    address public immutable token;
    address public immutable uni;
    address public immutable devRecipient;
    /// @notice The graph deployer (the Programmable Graph Factory); it alone calls `initialize`, once.
    address public immutable deployer;
    /// @notice Normal fees (platform, developer, bounty, holders), each payable only to its recipient. CREATE child 1.
    UN1FeeVault public immutable feeVault;
    /// @notice Buyer authentication, opening tax and its exemptions. CREATE child 2.
    UN1ProtectionModule public immutable protectionModule;
    /// @notice Opening taxes, payable only to the platform treasury. CREATE child 3.
    UN1OpeningTaxVault public immutable openingTaxVault;

    // ---------------- state ----------------
    // set once by `initialize` (they are deployed after the hook, which they reference)
    address public distributor;
    address public beacon;
    PoolId public poolId;
    uint40 public launchedAt;
    uint64 public swapCount;
    /// @notice Dev fee (UNI) paid by the buys whose slots target `round`: the most the beacon pays for revealing it.
    mapping(uint64 round => uint256 amount) public devFeeOf;
    /// @notice Tokens each buyer bought during the protection window (sells do not give room back).
    mapping(address buyer => uint256 amount) public boughtDuringProtection;

    uint256 private constant T_PIPS = uint256(keccak256("un1.hook.pips"));
    uint256 private constant T_NORMAL = uint256(keccak256("un1.hook.normal-pips"));
    uint256 private constant T_BUYER = uint256(keccak256("un1.hook.buyer"));

    error NotPoolManager();
    error HookNotImplemented();
    error WrongPool();
    error PartialQuoteFill();
    error BuyerLimitExceeded(address buyer, uint256 bought, uint256 limit);
    error NotDeployer();
    error AlreadyInitialized();
    error NotInitialized();
    error BadBeacon();

    event FeeTaken(bool buy, uint256 gross, uint256 platform, uint256 dev, uint256 holders);
    event OpeningFeeTaken(address indexed buyer, uint256 gross, uint256 amount);

    modifier onlyPoolManager() {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        _;
    }

    /// @param exempt Wallets exempt from the opening tax besides the developer; the module checks them as the reference
    ///        module does (zero entries are unused; no duplicates; never the developer, the hook, the token, the
    ///        PoolManager or the router).
    constructor(IPoolManager poolManager_, address token_, address uni_, address devRecipient_, address[6] memory exempt) {
        poolManager = poolManager_;
        token = token_;
        uni = uni_;
        devRecipient = devRecipient_;
        deployer = msg.sender;
        feeVault = new UN1FeeVault(poolManager_, uni_, devRecipient_);
        protectionModule = new UN1ProtectionModule(token_, address(poolManager_), devRecipient_, exempt);
        openingTaxVault = new UN1OpeningTaxVault(poolManager_, uni_);
        Hooks.validateHookPermissions(IHooks(address(this)), getHookPermissions());
    }

    function getHookPermissions() public pure returns (Hooks.Permissions memory) {
        return Hooks.Permissions({
            beforeInitialize: true,
            afterInitialize: false,
            beforeAddLiquidity: false,
            afterAddLiquidity: true,
            beforeRemoveLiquidity: false,
            afterRemoveLiquidity: true,
            beforeSwap: true,
            afterSwap: true,
            beforeDonate: false,
            afterDonate: false,
            beforeSwapReturnDelta: true,
            afterSwapReturnDelta: true,
            afterAddLiquidityReturnDelta: false,
            afterRemoveLiquidityReturnDelta: false
        });
    }

    /// @notice Wire the fee recipients, here and in the normal-fee vault. Deployer only, once, before the pool exists.
    ///         The beacon (public infrastructure deployed before the launch) must be bound to this hook's token.
    function initialize(address distributor_, address beacon_) external {
        if (msg.sender != deployer) revert NotDeployer();
        if (distributor != address(0)) revert AlreadyInitialized();
        (bool ok, bytes memory ret) = beacon_.staticcall(abi.encodeWithSignature("token()"));
        if (!ok || ret.length != 32 || abi.decode(ret, (uint256)) != uint160(token)) revert BadBeacon();
        distributor = distributor_;
        beacon = beacon_;
        feeVault.bind(distributor_, beacon_);
    }

    // ================= views =================

    function poolKey() public view returns (PoolKey memory) {
        (address c0, address c1) = quoteIsCurrency0() ? (uni, token) : (token, uni);
        return PoolKey({
            currency0: Currency.wrap(c0),
            currency1: Currency.wrap(c1),
            fee: LP_FEE,
            tickSpacing: TICK_SPACING,
            hooks: IHooks(address(this))
        });
    }

    /// @notice Whether UNI is currency0 of the pool. Computed, not stored: the launch graph binds immutables only to
    ///         literals or target addresses, and this depends on the token's CREATE2 address.
    function quoteIsCurrency0() public view returns (bool) {
        return uni < token;
    }

    /// @notice The halving fee of the current epoch, in pips.
    function halvingFee() public view returns (uint256) {
        uint256 epoch = IUN1Token(token).composeCount() / EPOCH;
        return epoch >= 32 ? 0 : HALVING_FEE >> epoch;
    }

    /// @notice Total fee per swap, in pips, outside the opening seconds.
    function totalFee() public view returns (uint256) {
        return PLATFORM_FEE + DEV_FEE + halvingFee();
    }

    /// @notice When launch protection ends (0 before the pool exists).
    function protectionEndsAt() public view returns (uint256) {
        return launchedAt == 0 ? 0 : uint256(launchedAt) + PROTECTION;
    }

    /// @notice Opening tax a buy by `buyer` pays now, in pips (the protection module's rule; exempt wallets pay none).
    function openingFee(address buyer) public view returns (uint256) {
        return protectionModule.openingTax(buyer, totalFee());
    }

    /// @notice Total fee of a buy by `buyer` now, in pips.
    function buyFee(address buyer) external view returns (uint256) {
        return totalFee() + openingFee(buyer);
    }

    // ================= initialize =================

    function beforeInitialize(address, PoolKey calldata key, uint160) external onlyPoolManager returns (bytes4) {
        if (distributor == address(0)) revert NotInitialized();
        PoolKey memory k = poolKey();
        if (
            PoolId.unwrap(poolId) != 0 || Currency.unwrap(key.currency0) != Currency.unwrap(k.currency0)
                || Currency.unwrap(key.currency1) != Currency.unwrap(k.currency1) || key.fee != LP_FEE
                || key.tickSpacing != TICK_SPACING
        ) revert WrongPool();
        poolId = key.toId();
        launchedAt = uint40(block.timestamp);
        IUN1Token(token).startProtection(); // from now on the token also caps what each address receives
        return IHooks.beforeInitialize.selector;
    }

    // ================= swap =================

    function beforeSwap(address sender, PoolKey calldata key, IPoolManager.SwapParams calldata params, bytes calldata)
        external
        onlyPoolManager
        returns (bytes4, BeforeSwapDelta, uint24)
    {
        if (PoolId.unwrap(key.toId()) != PoolId.unwrap(poolId)) revert WrongPool();
        uint256 normal = totalFee();
        uint256 pips = normal;
        if (_isBuy(params) && block.timestamp < uint256(launchedAt) + PROTECTION) {
            // the pool's first swap is the launch buy, atomic with pool creation and required by the Seeder
            address buyer = protectionModule.protectedBuyer(sender, swapCount == 0);
            _tstore(T_BUYER, uint160(buyer));
            pips += protectionModule.openingTax(buyer, normal);
        }
        _tstore(T_PIPS, pips);
        _tstore(T_NORMAL, normal);

        if (!_quoteSpecified(params)) return (IHooks.beforeSwap.selector, BeforeSwapDeltaLibrary.ZERO_DELTA, 0);
        (uint256 gross, uint256 fee) = _feeOnSpecified(params, pips);
        _accrue(_isBuy(params), gross, fee);
        return (IHooks.beforeSwap.selector, toBeforeSwapDelta(fee.toInt128(), 0), 0);
    }

    function afterSwap(
        address,
        PoolKey calldata,
        IPoolManager.SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata hookData
    ) external onlyPoolManager returns (bytes4, int128) {
        (int128 q, int128 t) = quoteIsCurrency0() ? (delta.amount0(), delta.amount1()) : (delta.amount1(), delta.amount0());
        int128 hookFee = _feeAfter(params, _abs(q));

        uint256 tokenAmount = _abs(t);
        if (_isBuy(params)) {
            if (block.timestamp < uint256(launchedAt) + PROTECTION) {
                address buyer = address(uint160(_tload(T_BUYER)));
                uint256 bought = boughtDuringProtection[buyer] + tokenAmount;
                if (bought > BUYER_LIMIT) revert BuyerLimitExceeded(buyer, bought, BUYER_LIMIT);
                boughtDuringProtection[buyer] = bought;
            }
            // the Seeder's launch buy goes to the developer as plain tokens: dealing its slots would not fit the launch
            // transaction (EIP-7825), and the launch deals no card
            bool launchBuy = swapCount == 0 && hookData.length == 32 && bytes32(hookData) == LAUNCH_BUY;
            IUN1Token(token).authorize(0, tokenAmount, launchBuy ? 0 : tokenAmount);
        } else {
            IUN1Token(token).authorize(tokenAmount, 0, 0);
        }
        swapCount++;
        return (IHooks.afterSwap.selector, hookFee);
    }

    /// @dev UNI specified: the fee was taken in beforeSwap on the requested amount, so the pool must have moved exactly
    ///      that amount. UNI unspecified: take the fee now from the UNI leg.
    function _feeAfter(IPoolManager.SwapParams calldata params, uint256 quoteAmount) private returns (int128) {
        uint256 pips = _tload(T_PIPS);
        bool exactIn = params.amountSpecified < 0;
        if (_quoteSpecified(params)) {
            (uint256 g, uint256 f) = _feeOnSpecified(params, pips);
            if (quoteAmount != (exactIn ? g - f : g)) revert PartialQuoteFill();
            return 0;
        }
        uint256 fee = exactIn ? FeeMath.onGross(quoteAmount, pips) : FeeMath.onNet(quoteAmount, pips);
        _accrue(_isBuy(params), exactIn ? quoteAmount : quoteAmount + fee, fee);
        return fee.toInt128();
    }

    // ================= liquidity: naked tokens only, never a draw =================

    function afterAddLiquidity(
        address,
        PoolKey calldata key,
        IPoolManager.ModifyLiquidityParams calldata,
        BalanceDelta delta,
        BalanceDelta,
        bytes calldata
    ) external onlyPoolManager returns (bytes4, BalanceDelta) {
        _authorizeLiquidity(key, delta);
        return (IHooks.afterAddLiquidity.selector, BalanceDeltaLibrary.ZERO_DELTA);
    }

    function afterRemoveLiquidity(
        address,
        PoolKey calldata key,
        IPoolManager.ModifyLiquidityParams calldata,
        BalanceDelta delta,
        BalanceDelta,
        bytes calldata
    ) external onlyPoolManager returns (bytes4, BalanceDelta) {
        _authorizeLiquidity(key, delta);
        return (IHooks.afterRemoveLiquidity.selector, BalanceDeltaLibrary.ZERO_DELTA);
    }

    function _authorizeLiquidity(PoolKey calldata key, BalanceDelta delta) private {
        if (PoolId.unwrap(key.toId()) != PoolId.unwrap(poolId)) revert WrongPool();
        int128 t = quoteIsCurrency0() ? delta.amount1() : delta.amount0();
        if (t < 0) IUN1Token(token).authorizeLiquidity(_abs(t), 0);
        else if (t > 0) IUN1Token(token).authorizeLiquidity(0, _abs(t));
    }

    // ================= fees =================

    /// @dev UNI is the specified side iff (currency0 is specified) == (UNI is currency0); currency0 is specified iff
    ///      exactInput == zeroForOne.
    function _quoteSpecified(IPoolManager.SwapParams calldata p) private view returns (bool) {
        return ((p.amountSpecified < 0) == p.zeroForOne) == quoteIsCurrency0();
    }

    /// @dev A buy pays UNI into the pool: zeroForOne when UNI is currency0.
    function _isBuy(IPoolManager.SwapParams calldata p) private view returns (bool) {
        return p.zeroForOne == quoteIsCurrency0();
    }

    function _feeOnSpecified(IPoolManager.SwapParams calldata p, uint256 pips) private pure returns (uint256 gross, uint256 fee) {
        bool exactIn = p.amountSpecified < 0;
        uint256 requested = exactIn ? uint256(-p.amountSpecified) : uint256(p.amountSpecified);
        fee = exactIn ? FeeMath.onGross(requested, pips) : FeeMath.onNet(requested, pips);
        gross = exactIn ? requested : requested + fee;
    }

    /// @dev Mint the fee as UNI claims to the vaults, so a swap never depends on a recipient. An opening tax is the part
    ///      above the normal fee of the same gross amount: it goes to the opening-tax vault (platform treasury only), and
    ///      the normal fee is split as usual into the normal-fee vault's ledgers.
    function _accrue(bool buy, uint256 gross, uint256 fee) private {
        if (fee == 0) return;
        uint256 normal = _tload(T_NORMAL);
        uint256 id = uint256(uint160(uni));
        if (_tload(T_PIPS) > normal) {
            uint256 normalFee = Math.min(fee, Math.mulDiv(gross, normal, FeeMath.ONE));
            uint256 extra = fee - normalFee;
            poolManager.mint(address(openingTaxVault), id, extra);
            openingTaxVault.recordTax(extra);
            emit OpeningFeeTaken(address(uint160(_tload(T_BUYER))), gross, extra);
            fee = normalFee;
            if (fee == 0) return;
        }
        uint256 platform = FeeMath.share(gross, fee, PLATFORM_FEE);
        uint256 dev = FeeMath.share(gross, fee - platform, DEV_FEE);
        uint256 holders = fee - platform - dev;
        if (buy) devFeeOf[DrandRound.target(block.timestamp)] += dev; // the round the token targets for this buy
        // the reserve is what the beacon can still claim plus the UNI it already holds
        uint256 reserve = feeVault.bountyAccrued() + IBalanceOf(uni).balanceOf(beacon);
        uint256 topUp;
        if (reserve < BOUNTY_RESERVE) {
            topUp = BOUNTY_RESERVE - reserve;
            if (topUp > dev) topUp = dev;
        }
        poolManager.mint(address(feeVault), id, fee);
        feeVault.recordFees(platform, dev - topUp, topUp, holders);
        emit FeeTaken(buy, gross, platform, dev - topUp, holders);
    }

    // ================= helpers =================

    function _abs(int128 x) private pure returns (uint256) {
        return x < 0 ? uint256(-int256(x)) : uint256(int256(x));
    }

    function _tstore(uint256 slot, uint256 v) private {
        assembly ("memory-safe") {
            tstore(slot, v)
        }
    }

    function _tload(uint256 slot) private view returns (uint256 v) {
        assembly ("memory-safe") {
            v := tload(slot)
        }
    }

    // ================= unused callbacks =================

    function afterInitialize(address, PoolKey calldata, uint160, int24) external pure returns (bytes4) {
        revert HookNotImplemented();
    }

    function beforeAddLiquidity(address, PoolKey calldata, IPoolManager.ModifyLiquidityParams calldata, bytes calldata)
        external
        pure
        returns (bytes4)
    {
        revert HookNotImplemented();
    }

    function beforeRemoveLiquidity(address, PoolKey calldata, IPoolManager.ModifyLiquidityParams calldata, bytes calldata)
        external
        pure
        returns (bytes4)
    {
        revert HookNotImplemented();
    }

    function beforeDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert HookNotImplemented();
    }

    function afterDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert HookNotImplemented();
    }
}

src/UN1Mirror.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IUN1TokenForMirror {
    function idCount(address account) external view returns (uint256);
    function ownerOfId(uint256 id) external view returns (address);
    function mirrorTransfer(address from, address to, uint256 id) external;
    function cardOf(uint256 id) external view returns (address owner, uint8 mask, uint8 layers, uint64 look);
    function commitmentOf(uint256 id) external view returns (bytes32);
    function detailsOf(uint256 id) external view returns (uint256);
}

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

interface IUN1Renderer {
    function render(uint256 id, uint8 mask, uint8 layers, uint64 look, uint256 details, bytes32 commitment)
        external
        view
        returns (bytes memory image, bytes memory uri);
}

/// @title UN1Mirror
/// @notice ERC721 view of the cards held in UN1Token (DN404 style): the token is the source of truth, the mirror emits
///  the events and keeps NFT approvals. Moving a card here moves exactly one token with it. Deployed before the launch as
///  public infrastructure (CREATE2 proxy), bound to the token's predicted address; the token checks the binding in its
///  initializer.
contract UN1Mirror {
    address public immutable token;
    address public immutable renderer;

    mapping(uint256 id => address) public getApproved;
    mapping(address owner => mapping(address operator => bool)) public isApprovedForAll;

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);
    event MetadataUpdate(uint256 tokenId); // ERC-4906

    error NotToken();
    error NotAuthorized();
    error NonexistentToken();
    error ZeroAddress();
    error UnsafeRecipient();

    constructor(address token_, address renderer_) {
        token = token_;
        renderer = renderer_;
    }

    // ================= ERC721 =================

    function name() external pure returns (string memory) {
        return "Un1corn";
    }

    function symbol() external pure returns (string memory) {
        return "UN1";
    }

    function tokenURI(uint256 id) external view returns (string memory) {
        (address owner, uint8 mask, uint8 layers, uint64 look) = IUN1TokenForMirror(token).cardOf(id);
        if (owner == address(0)) revert NonexistentToken();
        if (renderer == address(0)) return "";
        return string(_render(id, mask, layers, look));
    }

    function _render(uint256 id, uint8 mask, uint8 layers, uint64 look) private view returns (bytes memory uri) {
        IUN1TokenForMirror t = IUN1TokenForMirror(token);
        uint256 details = t.detailsOf(id);
        bytes32 commitment = t.commitmentOf(id);
        (, uri) = IUN1Renderer(renderer).render(id, mask, layers, look, details, commitment);
    }

    function balanceOf(address owner) external view returns (uint256) {
        if (owner == address(0)) revert ZeroAddress();
        return IUN1TokenForMirror(token).idCount(owner);
    }

    function ownerOf(uint256 id) public view returns (address owner) {
        owner = IUN1TokenForMirror(token).ownerOfId(id);
        if (owner == address(0)) revert NonexistentToken();
    }

    function approve(address spender, uint256 id) external {
        address owner = ownerOf(id);
        if (msg.sender != owner && !isApprovedForAll[owner][msg.sender]) revert NotAuthorized();
        getApproved[id] = spender;
        emit Approval(owner, spender, id);
    }

    function setApprovalForAll(address operator, bool approved) external {
        isApprovedForAll[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function transferFrom(address from, address to, uint256 id) public {
        if (to == address(0)) revert ZeroAddress();
        if (ownerOf(id) != from) revert NotAuthorized();
        if (msg.sender != from && !isApprovedForAll[from][msg.sender] && getApproved[id] != msg.sender) revert NotAuthorized();
        IUN1TokenForMirror(token).mirrorTransfer(from, to, id);
    }

    function safeTransferFrom(address from, address to, uint256 id) external {
        safeTransferFrom(from, to, id, "");
    }

    /// @dev State is fully updated before the receiver callback (audit E-2).
    function safeTransferFrom(address from, address to, uint256 id, bytes memory data) public {
        transferFrom(from, to, id);
        if (to.code.length != 0) {
            if (IERC721Receiver(to).onERC721Received(msg.sender, from, id, data) != IERC721Receiver.onERC721Received.selector) {
                revert UnsafeRecipient();
            }
        }
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x01ffc9a7 // ERC165
            || interfaceId == 0x80ac58cd // ERC721
            || interfaceId == 0x5b5e139f // ERC721Metadata
            || interfaceId == 0x49064906; // ERC4906
    }

    // ================= token hooks =================

    function logTransfer(address from, address to, uint256 id) external {
        if (msg.sender != token) revert NotToken();
        delete getApproved[id];
        emit Transfer(from, to, id);
    }

    function logMetadataUpdate(uint256 id) external {
        if (msg.sender != token) revert NotToken();
        emit MetadataUpdate(id);
    }
}

src/UN1OpeningTaxVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";

/// @title UN1OpeningTaxVault
/// @notice The opening-tax vault of the official pool, created by the hook (CREATE child 3, as in Programmable's launch
///  protection v1). During the first 30 seconds after the pool is created, a buy pays a total fee that starts at 99%
///  and falls linearly to the normal fee; the hook mints the part above the normal fee here as UNI claims (ERC-6909 in
///  the PoolManager). One ledger, payable only to the fixed platform treasury; anyone may pay the gas of a claim. No
///  owner, no allowances, no principal withdrawal, no arbitrary calls.
contract UN1OpeningTaxVault is IUnlockCallback {
    address public constant PLATFORM_RECIPIENT = 0xD88539d3c4C460136a733A3Fd60cf6BF269079da;

    IPoolManager public immutable poolManager;
    address public immutable kernel; // the hook
    address public immutable uni;

    /// @notice Opening tax not yet paid to the platform treasury.
    uint256 public accrued;
    /// @notice All opening tax ever recorded.
    uint256 public totalRecorded;

    error NotKernel();
    error NotPoolManager();
    error InsufficientFeeBacking();
    error NothingToClaim();

    event TaxRecorded(uint256 amount);
    event TaxClaimed(uint256 amount);

    constructor(IPoolManager poolManager_, address uni_) {
        poolManager = poolManager_;
        kernel = msg.sender;
        uni = uni_;
    }

    /// @notice Record an opening tax whose UNI claims the hook has just minted to this vault.
    function recordTax(uint256 amount) external {
        if (msg.sender != kernel) revert NotKernel();
        accrued += amount;
        totalRecorded += amount;
        if (poolManager.balanceOf(address(this), uint256(uint160(uni))) < accrued) revert InsufficientFeeBacking();
        emit TaxRecorded(amount);
    }

    /// @notice Pay everything accrued to the platform treasury.
    function claim() external returns (uint256 amount) {
        amount = accrued;
        if (amount == 0) revert NothingToClaim();
        accrued = 0;
        poolManager.unlock(abi.encode(amount));
        emit TaxClaimed(amount);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        uint256 amount = abi.decode(data, (uint256));
        poolManager.burn(address(this), uint256(uint160(uni)), amount);
        poolManager.take(Currency.wrap(uni), PLATFORM_RECIPIENT, amount);
        return "";
    }
}

src/UN1ProtectionModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/// @dev The Universal Router reports the account that called it (the v4 locker) to hooks.
interface IMsgSender {
    function msgSender() external view returns (address);
}

interface IUN1Kernel {
    function launchedAt() external view returns (uint40);
}

/// @title UN1ProtectionModule
/// @notice The launch protection policy of the official pool (Programmable launch protection v1, with UNI as the
///  quote), created by the hook (CREATE child 2). Immutable and read-only; the hook asks it, during a swap:
///  - who is buying during the 5-minute protection window: the launch buy (the pool's first swap, made by the Seeder
///    in the launch transaction) is the developer's; every other buy must come from the canonical Universal Router,
///    whose msgSender is the buyer. The hook caps each buyer at 2% of supply; the token caps each recipient the same
///  - the opening tax of a buy: for the first 30 seconds the total buy fee starts at 99% and falls linearly to the normal
///    fee. The hook mints the extra to the opening-tax vault, payable only to the platform treasury
///  - who pays no opening tax: the developer and up to six wallets fixed here. They keep both 2% limits
contract UN1ProtectionModule {
    uint256 public constant PROTECTION = 5 minutes;
    uint256 public constant OPENING_FEE_WINDOW = 30 seconds;
    uint256 public constant OPENING_TOTAL_FEE = 990_000; // pips: 99% of a buy at the pool's first second
    /// @notice The canonical Universal Router (Uniswap, mainnet). During protection it is the only way to buy.
    address public constant ROUTER = 0xd92A36B0000531EF3063dEd4De20A0783308446C;

    address public immutable kernel; // the hook
    address public immutable token;
    address public immutable poolManager;
    address public immutable developer;
    /// @notice The router's code when the hook was deployed (in the launch transaction): buys during protection must
    ///         come from that exact code.
    bytes32 public immutable routerCodeHash;
    address private immutable exempt0;
    address private immutable exempt1;
    address private immutable exempt2;
    address private immutable exempt3;
    address private immutable exempt4;
    address private immutable exempt5;

    error OnlyKernel();
    error InvalidExemption();
    error UnsupportedRouter();
    error InvalidBuyer();

    /// @param exempt Wallets exempt from the opening tax besides the developer, as the reference module checks them:
    ///        zero entries are unused; no duplicates; never the developer, the hook, the token, the PoolManager or the
    ///        router.
    constructor(address token_, address poolManager_, address developer_, address[6] memory exempt) {
        for (uint256 i; i < 6; ++i) {
            address w = exempt[i];
            if (w == address(0)) continue;
            if (w == developer_ || w == msg.sender || w == token_ || w == poolManager_ || w == ROUTER) revert InvalidExemption();
            for (uint256 j; j < i; ++j) {
                if (w == exempt[j]) revert InvalidExemption();
            }
        }
        kernel = msg.sender;
        token = token_;
        poolManager = poolManager_;
        developer = developer_;
        routerCodeHash = ROUTER.codehash;
        (exempt0, exempt1, exempt2, exempt3, exempt4, exempt5) = (exempt[0], exempt[1], exempt[2], exempt[3], exempt[4], exempt[5]);
    }

    /// @notice The six wallet slots exempt from the opening tax besides the developer (0 = unused).
    function exemptWallets() external view returns (address[6] memory) {
        return [exempt0, exempt1, exempt2, exempt3, exempt4, exempt5];
    }

    /// @notice Whether `wallet` pays no opening tax: the developer and the exempt wallets.
    function isExempt(address wallet) public view returns (bool) {
        return wallet != address(0)
            && (wallet == developer || wallet == exempt0 || wallet == exempt1 || wallet == exempt2 || wallet == exempt3
                || wallet == exempt4 || wallet == exempt5);
    }

    /// @notice Opening tax a buy by `buyer` pays now, in pips, on top of the normal fee `normal` (pips): (99% minus the
    ///         normal fee) at the pool's first second, falling linearly to 0 over 30 seconds; 0 for exempt wallets.
    function openingTax(address buyer, uint256 normal) public view returns (uint256) {
        uint256 start = IUN1Kernel(kernel).launchedAt();
        if (start == 0 || block.timestamp >= start + OPENING_FEE_WINDOW || isExempt(buyer)) return 0;
        return Math.mulDiv(OPENING_TOTAL_FEE - normal, start + OPENING_FEE_WINDOW - block.timestamp, OPENING_FEE_WINDOW);
    }

    /// @notice The buyer of a buy during protection, for the hook. `sender` is the PoolManager's swap caller;
    ///         `launchBuy` is true for the pool's first swap, which the launch makes for the developer.
    function protectedBuyer(address sender, bool launchBuy) external view returns (address buyer) {
        if (msg.sender != kernel) revert OnlyKernel();
        if (launchBuy) return developer;
        if (sender != ROUTER || sender.codehash != routerCodeHash) revert UnsupportedRouter();
        buyer = IMsgSender(sender).msgSender();
        if (buyer == address(0) || buyer == ROUTER || buyer == kernel || buyer == poolManager) revert InvalidBuyer();
    }
}

src/UN1Renderer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {Buf} from "./libraries/Buf.sol";
import {Polish} from "./libraries/Polish.sol";

/// @title UN1Renderer
/// @notice Fully on-chain SVG and metadata, art v7. Byte-for-byte the same as art/render_onchain.py (tested on fixtures).
///  32×32 cells of 10 units. Parts are drawn in priority order from 64 bitmaps (data contract `parts`, 256 bytes per
///  variant: 32 rows of all cells, then 32 rows of accent cells; bit 31 of a row is x = 0). An owned part's bitmap is
///  polished with its 32-bit detail (libraries/Polish.sol) and filled with its measured colours; the other parts keep
///  their plain shape and are written, faded, with the hex characters of the card's provenance commitment.
///  Stateless and independent of the token, so it is deployed before the launch as public infrastructure (the launch
///  transaction must stay under the EIP-7825 gas cap); the mirror reads the card and calls `render`.
contract UN1Renderer {
    using Buf for Buf.B;
    using Strings for uint256;

    bytes32 public constant PARTS_SHA256 = 0x803964e797696b1abdaec6e3ef62729f9b593fdb4436af33d99517e7204fccb5;
    uint256 private constant N = 32;
    uint256 private constant FULL = 0xffffffff;

    address public immutable parts;

    error BadParts();

    constructor(address parts_) {
        parts = parts_;
        if (parts_.code.length != 1 + 512 * 33 || _partsHash(parts_) != PARTS_SHA256) revert BadParts();
    }

    // ================= entry points =================

    /// @notice Render any card state (used by tokenURI, the website and the tests).
    function render(uint256 id, uint8 mask, uint8 layers, uint64 look, uint256 details, bytes32 commitment)
        public
        view
        returns (bytes memory image, bytes memory uri)
    {
        image = svg(id, mask, look, details, commitment);
        Buf.B memory j = Buf.init(image.length * 4 / 3 + 4096);
        j.add('{"name":"UN1 #');
        j.adds(_pad4(id));
        j.add('","description":"Fragment of Bitcoin block ');
        j.adds(_thousands(id - 1));
        j.add(". ");
        j.adds(_popcount(mask).toString());
        j.add(' of 8 qubits measured. Composition adds a layer of SHA-256.","image":"data:image/svg+xml;base64,');
        j.adds(Base64.encode(image));
        j.add('","attributes":[');
        _attributes(j, id, mask, layers, look);
        j.add("]}");
        uri = abi.encodePacked("data:application/json;base64,", Base64.encode(j.done()));
    }

    // ================= SVG =================

    struct Layout {
        uint256[N] occ;
        uint256[N] owned;
        uint256[N][8] cells;
        uint256[N][8] accs;
        uint256[N] t3; // the eyes' recognition cell (tone 3)
    }

    function svg(uint256 id, uint8 mask, uint64 look, uint256 details, bytes32 commitment) public view returns (bytes memory) {
        Layout memory l = _layout(mask, look, details);
        uint256 g = (look >> 56) & 3;
        Buf.B memory b = Buf.init(100_000);
        b.add('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 320" shape-rendering="crispEdges">');
        b.add('<rect width="320" height="320" fill="');
        b.add(_groundColor(g, 0));
        b.add('"/>');
        _outline(b, l, _groundColor(g, 1));
        _owned(b, l, look);
        _unowned(b, l, commitment, _groundColor(g, 2));
        _idBlock(b, id, mask, g);
        b.add("</svg>");
        return b.done();
    }

    /// @dev Priority: eyes, horn, ears, muzzle, swirl, face, upper mane, lower mane (part indices 0 1 2 4 7 3 5 6).
    function _layout(uint8 mask, uint64 look, uint256 details) private view returns (Layout memory l) {
        uint256 order = 0x01020407030506; // one byte per part index, first to last
        for (uint256 k; k < 8; ++k) {
            uint256 i = (order >> (8 * (7 - k))) & 0xff;
            bool has = (mask >> i) & 1 == 1;
            uint256 shape = has ? (look >> (7 * i)) & 7 : 0;
            bytes memory d = _variant(i, shape);
            Polish.Part memory p;
            for (uint256 y; y < N; ++y) (p.cells[y], p.acc[y]) = (_row(d, y), _row(d, N + y));
            if (has) Polish.polish(i, shape, p, (details >> (224 - 32 * i)) & FULL);
            for (uint256 y; y < N; ++y) {
                uint256 c = p.cells[y] & ~l.occ[y] & FULL;
                l.occ[y] |= c;
                l.cells[i][y] = c;
                l.accs[i][y] = p.acc[y] & c;
                if (has) l.owned[y] |= c;
                if (i == 0) l.t3[y] = p.t3[y] & c;
            }
        }
    }

    function _ring(uint256[N] memory r, uint256 y) private pure returns (uint256 n) {
        n = ((r[y] << 1) | (r[y] >> 1)) & FULL;
        if (y > 0) n |= r[y - 1];
        if (y < N - 1) n |= r[y + 1];
    }

    /// @dev Outline cells next to an owned part in full; cells next only to parts not owned at 40%.
    function _outline(Buf.B memory b, Layout memory l, bytes memory edge) private pure {
        uint256[N] memory ghost;
        bool anyGhost;
        for (uint256 y; y < N; ++y) {
            uint256 nearOwned = _ring(l.owned, y);
            _runs(b, nearOwned & ~l.occ[y] & FULL, y, edge);
            ghost[y] = _ring(l.occ, y) & ~nearOwned & ~l.occ[y] & FULL;
            if (ghost[y] != 0) anyGhost = true;
        }
        if (!anyGhost) return;
        b.add('<g opacity="0.4">');
        for (uint256 y; y < N; ++y) _runs(b, ghost[y], y, edge);
        b.add("</g>");
    }

    /// @dev Owned cells row by row, consecutive cells of the same colour merged into one rect.
    function _owned(Buf.B memory b, Layout memory l, uint64 look) private pure {
        for (uint256 y; y < N; ++y) {
            uint256 row = l.owned[y];
            uint256 x;
            while (x < N) {
                if ((row >> (31 - x)) & 1 == 0) {
                    ++x;
                    continue;
                }
                uint256 key = _colorKey(l, look, x, y);
                uint256 s = x;
                ++x;
                while (x < N && (row >> (31 - x)) & 1 == 1 && _colorKey(l, look, x, y) == key) ++x;
                _rect(b, s * 10, y * 10, (x - s) * 10, 10, _fill(key));
            }
        }
    }

    /// @dev One number per distinct fill: 24-bit colours below 2^24; rainbow cells (never equal to a neighbour) above.
    function _colorKey(Layout memory l, uint64 look, uint256 x, uint256 y) private pure returns (uint256) {
        uint256 bit = uint256(1) << (31 - x);
        uint256 i;
        while (l.cells[i][y] & bit == 0) ++i;
        uint256 ph = (look >> (7 * i + 3)) & 15;
        // the recognition cell belongs to the eye phase: white on Ink eyes, ink on every other phase
        if (i == 0 && l.t3[y] & bit != 0) return ph == 0 ? 0xffffff : 0x111111;
        uint256 tone = l.accs[i][y] & bit != 0 ? 2 : 1;
        if (_isRainbow(i, ph)) return (1 << 32) | (((x * 9 + y * 6) % 360) << 8) | tone;
        return _phaseRgb(i, ph, tone);
    }

    function _fill(uint256 key) private pure returns (bytes memory) {
        if (key >> 32 == 0) return _hex24(key);
        return abi.encodePacked("hsl(", ((key >> 8) & 0xffff).toString(), ",95%,", key & 0xff == 2 ? "74" : "60", "%)");
    }

    function _unowned(Buf.B memory b, Layout memory l, bytes32 commitment, bytes memory fill) private pure {
        b.add('<g font-family="monospace" font-size="9.5" text-anchor="middle" fill="');
        b.add(fill);
        b.add('" opacity="0.68">');
        uint256 k;
        for (uint256 y; y < N; ++y) {
            uint256 row = l.occ[y] & ~l.owned[y] & FULL;
            if (row == 0) continue;
            b.add('<text x="');
            bool first = true;
            for (uint256 x; x < N; ++x) {
                if ((row >> (31 - x)) & 1 == 0) continue;
                if (!first) b.add(" ");
                first = false;
                b.adds((x * 10 + 5).toString());
            }
            b.add('" y="');
            b.adds((y * 10 + 8).toString());
            b.add('.2">');
            for (uint256 x; x < N; ++x) {
                if ((row >> (31 - x)) & 1 == 0) continue;
                b.addByte(_hexChar(commitment, k % 64));
                ++k;
            }
            b.add("</text>");
        }
        b.add("</g>");
    }

    /// @dev Bottom-left: the id in a 3×5 pixel font, then 8 qubit dots (filled = part owned). No fonts involved.
    function _idBlock(Buf.B memory b, uint256 id, uint8 mask, uint256 g) private pure {
        bytes memory ink = _ink(g);
        bytes memory digits = bytes(_pad4(id));
        for (uint256 d; d < digits.length; ++d) {
            uint256 glyph = _glyph(uint8(digits[d]) - 48);
            for (uint256 k; k < 15; ++k) {
                if ((glyph >> (14 - k)) & 1 == 0) continue;
                _rect(b, 10 + (d * 4 + k % 3) * 4, 270 + (k / 3) * 4, 4, 4, ink);
            }
        }
        bytes memory dim = _groundColor(g, 2);
        for (uint256 i; i < 8; ++i) {
            if ((mask >> i) & 1 == 1) {
                _rect(b, 10 + i * 12, 298, 8, 8, ink);
            } else {
                b.add('<rect x="');
                b.adds((10 + i * 12).toString());
                b.add('" y="298" width="8" height="8" fill="');
                b.add(dim);
                b.add('" opacity="0.68"/>');
            }
        }
    }

    // ================= drawing helpers =================

    function _runs(Buf.B memory b, uint256 row, uint256 y, bytes memory fill) private pure {
        uint256 x;
        while (x < N) {
            if ((row >> (31 - x)) & 1 == 0) {
                ++x;
                continue;
            }
            uint256 s = x;
            while (x < N && (row >> (31 - x)) & 1 == 1) ++x;
            _rect(b, s * 10, y * 10, (x - s) * 10, 10, fill);
        }
    }

    function _rect(Buf.B memory b, uint256 x, uint256 y, uint256 w, uint256 h, bytes memory fill) private pure {
        b.add('<rect x="');
        b.adds(x.toString());
        b.add('" y="');
        b.adds(y.toString());
        b.add('" width="');
        b.adds(w.toString());
        b.add('" height="');
        b.adds(h.toString());
        b.add('" fill="');
        b.add(fill);
        b.add('"/>');
    }

    // ================= metadata =================

    function _attributes(Buf.B memory j, uint256 id, uint8 mask, uint8 layers, uint64 look) private pure {
        for (uint256 i; i < 8; ++i) {
            if ((mask >> i) & 1 == 0) continue;
            uint256 sh = (look >> (7 * i)) & 7;
            uint256 ph = (look >> (7 * i + 3)) & 15;
            j.add('{"trait_type":"');
            j.adds(_label(i));
            j.add('","value":"');
            j.adds(_shapeName(i, sh));
            j.add('"},{"trait_type":"');
            j.adds(_label(i));
            j.add(' Phase","value":"');
            j.adds(_phaseName(i, ph));
            j.add('"},');
        }
        uint256 g = (look >> 56) & 3;
        uint256 n = _popcount(mask);
        j.add('{"trait_type":"Ground","value":"');
        j.add(bytes(g == 0 ? "Paper" : g == 1 ? "Night" : "Satoshi"));
        j.add('"},{"trait_type":"Qubits","value":');
        j.adds(n.toString());
        j.add(',"display_type":"number","max_value":8},{"trait_type":"Level","value":"');
        j.add(bytes(mask == 0xff ? "V" : "-"));
        j.add('"},{"trait_type":"State","value":"');
        j.add(bytes(layers > 1 ? "Entangled" : "Measured"));
        j.add('"},{"trait_type":"Layers","value":');
        j.adds(uint256(layers).toString());
        j.add(',"display_type":"number"},{"trait_type":"Weight","value":');
        uint256 w = n * (10_000 + 200 * (uint256(layers) - 1) + (mask == 0xff ? 500 : 0));
        j.add(abi.encodePacked((w / 10_000).toString(), ".", _two((w % 10_000) / 100)));
        j.add(',"display_type":"number"},{"trait_type":"Rarity Score","value":');
        uint256 r = _rarity(mask, look);
        j.add(abi.encodePacked((r / 100).toString(), ".", ((r % 100) / 10).toString()));
        j.add(',"display_type":"number"},{"trait_type":"Bitcoin Block","value":');
        j.adds((id - 1).toString());
        j.add(',"display_type":"number"}');
    }

    /// @dev Sum of -log2(probability) in hundredths: ground plus shape and phase of every owned part.
    function _rarity(uint8 mask, uint64 look) private pure returns (uint256 s) {
        s = _pick16(0x0020011c0196, (look >> 56) & 3, 3);
        for (uint256 i; i < 8; ++i) {
            if ((mask >> i) & 1 == 0) continue;
            s += _pick16(0x00b800e801120132014c016c01b00234, (look >> (7 * i)) & 7, 8);
            uint256 ph = (look >> (7 * i + 3)) & 15;
            s += i == 0
                ? _pick16(0x009c00e8011c0132016c019601b00298, ph, 8)
                : _pick16(0x0000ce00e801320132015b016c018001d001fa0298, ph, 10);
        }
    }

    /// @dev k-th of n big-endian 16-bit values packed in `table`.
    function _pick16(uint256 table, uint256 k, uint256 n) private pure returns (uint256) {
        return (table >> (16 * (n - 1 - k))) & 0xffff;
    }

    function _label(uint256 i) private pure returns (string memory) {
        if (i == 0) return "Eyes";
        if (i == 1) return "Horn";
        if (i == 2) return "Ears";
        if (i == 3) return "Face";
        if (i == 4) return "Muzzle";
        if (i == 5) return "Upper Mane";
        if (i == 6) return "Lower Mane";
        return "Swirl";
    }

    function _shapeName(uint256 i, uint256 s) private pure returns (string memory) {
        string[8] memory n;
        if (i == 0) n = ["Round", "Calm", "Almond", "Lash", "Wide", "Sleepy", "Star", "Laser"];
        else if (i == 1) n = ["Ringed", "Plain", "Short", "Long", "Curved", "Spiral", "Twin", "Crystal"];
        else if (i == 2) n = ["Pointed", "Tall", "Short", "Swept", "Round", "Notched", "Tufted", "Twin"];
        else if (i == 3) n = ["Plain", "Blush", "Blaze", "Freckles", "Star", "Striped", "Moon", "Circuit"];
        else if (i == 4) n = ["Calm", "Smile", "Open", "Snort", "Freckles", "Tongue", "Ring", "Breath"];
        else if (i == 5) n = ["Wave", "Spiky", "Bare", "Full", "Curly", "Feather", "Flame", "Aurora"];
        else if (i == 6) n = ["Wave", "Spiky", "Long", "Short", "Braid", "Ribbon", "Full", "Comet"];
        else n = ["Curl", "Double", "Tight", "Ring", "Wave", "Knot", "Orbit", "Galaxy"];
        return n[s];
    }

    function _phaseName(uint256 i, uint256 ph) private pure returns (string memory) {
        if (i == 0) {
            string[8] memory e = ["Ink", "Magenta", "Violet", "Cyan", "Mint", "Gold", "Satoshi", "Rainbow"];
            return e[ph];
        }
        string[10] memory p = ["White", "Pink", "Lilac", "Silver", "Cyan", "Mint", "Violet", "Gold", "Satoshi", "Rainbow"];
        return p[ph];
    }

    // ================= colours =================

    function _isRainbow(uint256 i, uint256 ph) private pure returns (bool) {
        return i == 0 ? ph == 7 : ph == 9;
    }

    /// @dev tone 1 = main, 2 = accent. 6 hex digits each, packed.
    function _phaseRgb(uint256 i, uint256 ph, uint256 tone) private pure returns (uint256 c) {
        if (i == 0) {
            c = tone == 1
                ? _pick24(0x111111ff2fa68a4dff16c5e01fcf86e8a900f7931a, ph, 7)
                : _pick24(0xffffffffffffffffffffffffffffffffffffffe0b8, ph, 7);
        } else {
            c = tone == 1
                ? _pick24(0xffffffff2fa6b9a2ffb8c0d02fe6ff3df2a68a4dffffc531f7931a, ph, 9)
                : _pick24(0xd9d4ffff9ad4e4daffeef1f6c4f9ffc7fbe3c9aefffff0b3ffd199, ph, 9);
        }
    }

    /// @dev 0 bg, 1 edge, 2 hash. Paper / Night / Satoshi.
    function _groundColor(uint256 g, uint256 role) private pure returns (bytes memory) {
        uint256 c;
        if (g == 0) c = role == 0 ? 0xf2f0eb : role == 1 ? 0x111111 : 0xb5ae9f;
        else if (g == 1) c = role == 0 ? 0x071538 : role == 1 ? 0x2e3f8f : 0x4d6fc4;
        else c = role == 0 ? 0x111111 : role == 1 ? 0xf7931a : 0x7a4300;
        return _hex24(c);
    }

    function _ink(uint256 g) private pure returns (bytes memory) {
        return _hex24(g == 0 ? 0x111111 : g == 1 ? 0x8fa6e0 : 0xf7931a);
    }

    function _pick24(uint256 table, uint256 k, uint256 n) private pure returns (uint256) {
        return (table >> (24 * (n - 1 - k))) & 0xffffff;
    }

    function _hex24(uint256 c) private pure returns (bytes memory s) {
        s = new bytes(7);
        s[0] = "#";
        for (uint256 i; i < 6; ++i) s[1 + i] = _nibble((c >> (4 * (5 - i))) & 15);
    }

    // ================= small helpers =================

    /// @dev 256 logical bytes = 8 PUSH32 chunks of UN1PartsData (logical byte i at 2 + (i / 32) * 33 + (i % 32)).
    function _variant(uint256 part, uint256 shape) private view returns (bytes memory d) {
        d = new bytes(256);
        address p = parts;
        uint256 firstChunk = (part * 8 + shape) * 8;
        assembly ("memory-safe") {
            for { let j := 0 } lt(j, 8) { j := add(j, 1) } {
                extcodecopy(p, add(add(d, 0x20), mul(j, 32)), add(2, mul(add(firstChunk, j), 33)), 32)
            }
        }
    }

    function _row(bytes memory d, uint256 r) private pure returns (uint256 v) {
        assembly ("memory-safe") {
            v := shr(224, mload(add(add(d, 0x20), mul(r, 4))))
        }
    }

    function _partsHash(address p) private view returns (bytes32) {
        bytes memory d = new bytes(16_384);
        assembly ("memory-safe") {
            for { let j := 0 } lt(j, 512) { j := add(j, 1) } {
                extcodecopy(p, add(add(d, 0x20), mul(j, 32)), add(2, mul(j, 33)), 32)
            }
        }
        return sha256(d);
    }

    /// @dev 3×5 glyphs, row-major, MSB first.
    function _glyph(uint256 digit) private pure returns (uint256) {
        uint256[10] memory g =
            [uint256(0x7b6f), 0x2c97, 0x73e7, 0x73cf, 0x5bc9, 0x79cf, 0x79ef, 0x7292, 0x7bef, 0x7bcf];
        return g[digit];
    }

    function _hexChar(bytes32 h, uint256 k) private pure returns (uint8) {
        uint256 v = (uint256(h) >> (4 * (63 - k))) & 15;
        return uint8(_nibble(v));
    }

    function _nibble(uint256 v) private pure returns (bytes1) {
        return bytes1(uint8(v < 10 ? 48 + v : 87 + v));
    }

    function _pad4(uint256 id) private pure returns (string memory) {
        if (id >= 1000) return id.toString();
        if (id >= 100) return string.concat("0", id.toString());
        if (id >= 10) return string.concat("00", id.toString());
        return string.concat("000", id.toString());
    }

    function _thousands(uint256 n) private pure returns (string memory) {
        if (n < 1000) return n.toString();
        return string.concat((n / 1000).toString(), ",", _three(n % 1000));
    }

    function _three(uint256 n) private pure returns (string memory) {
        if (n >= 100) return n.toString();
        if (n >= 10) return string.concat("0", n.toString());
        return string.concat("00", n.toString());
    }

    function _two(uint256 n) private pure returns (string memory) {
        return n >= 10 ? n.toString() : string.concat("0", n.toString());
    }

    function _popcount(uint8 m) private pure returns (uint256 c) {
        for (; m != 0; m &= m - 1) ++c;
    }
}

